use std::fs

struct Bst {
    key: Vec<int>,
    l: Vec<int>,
    r: Vec<int>,
    root: int,
    found: bool,
}

impl Bst {
    fn contains(self, x: int) -> bool {
        let mut n = self.root
        while n >= 0 {
            let k = self.key[n as usize]
            if x == k { return true }
            if x < k { n = self.l[n as usize] } else { n = self.r[n as usize] }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.key.len() as int
        self.key.push(x)
        self.l.push(-1)
        self.r.push(-1)
        if self.root < 0 {
            self.root = id
            return
        }
        let mut n = self.root
        loop {
            if x < self.key[n as usize] {
                let c = self.l[n as usize]
                if c < 0 {
                    self.l[n as usize] = id
                    return
                }
                n = c
            } else {
                let c = self.r[n as usize]
                if c < 0 {
                    self.r[n as usize] = id
                    return
                }
                n = c
            }
        }
    }

    fn minnode(self, start: int) -> int {
        let mut n = start
        while self.l[n as usize] >= 0 { n = self.l[n as usize] }
        n
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 { return -1 }
        let k = self.key[n as usize]
        if x < k {
            let c = self.del(self.l[n as usize], x)
            self.l[n as usize] = c
            return n
        }
        if x > k {
            let c = self.del(self.r[n as usize], x)
            self.r[n as usize] = c
            return n
        }
        self.found = true
        let lc = self.l[n as usize]
        let rc = self.r[n as usize]
        if lc < 0 { return rc }
        if rc < 0 { return lc }
        let s = self.minnode(rc)
        let sk = self.key[s as usize]
        self.key[n as usize] = sk
        let c = self.del(rc, sk)
        self.r[n as usize] = c
        n
    }

    fn walk(self, n: int, out: Vec<string>) -> Vec<string> {
        let mut o = out
        if n < 0 { return o }
        o = self.walk(self.l[n as usize], o)
        o.push("${self.key[n as usize]}")
        o = self.walk(self.r[n as usize], o)
        o
    }

    fn height(self, n: int) -> int {
        if n < 0 { return 0 }
        let a = self.height(self.l[n as usize])
        let b = self.height(self.r[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Bst { key: [], l: [], r: [], root: -1, found: false }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            t.found = false
            let nr = t.del(t.root, x)
            t.root = nr
            if t.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let o: Vec<string> = t.walk(t.root, [])
            if o.len() == 0 { println("<empty>") } else { println(o.join(" ")) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else {
                let m = t.minnode(t.root)
                println("${t.key[m as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut n = t.root
                while t.r[n as usize] >= 0 { n = t.r[n as usize] }
                println("${t.key[n as usize]}")
            }
        }
    }
}

